import math

def build_agent(sandbox):
    GLASS_Y = 2.0
    CENTER_X = 6.0

    # Base beam (light and above the glass surface)
    base = sandbox.add_beam(
        x=CENTER_X, y=GLASS_Y + 0.025, width=0.05, height=0.05, angle=0, density=0.05
    )
    sandbox.weld_to_glass(base, (CENTER_X, GLASS_Y))

    # Create six bars to cover the full 12m length
    seg_centers = [1.0, 3.0, 5.0, 7.0, 9.0, 11.0]
    bars = []
    for cx in seg_centers:
        b = sandbox.add_beam(
            x=cx, y=GLASS_Y + 0.06, width=2.0, height=0.1, angle=0, density=0.04
        )
        sandbox.set_material_properties(b, restitution=0.0, friction=1.8)
        bars.append(b)

    # Connect bars with rigid joints to form a continuous sweeping structure
    for i in range(len(bars) - 1):
        jx = (seg_centers[i] + seg_centers[i + 1]) / 2.0
        sandbox.add_joint(
            bars[i], bars[i + 1], (jx, GLASS_Y + 0.06), type='rigid'
        )

    # Pivot joint at the end of the wiper for sweeping motion
    pivot = sandbox.add_joint(
        base, bars[-1], (bars[-1].position.x + 1.0, GLASS_Y + 0.06),
        type='pivot', lower_limit=-math.pi, upper_limit=math.pi
    )
    return {"body": base, "motors": [pivot]}

def agent_action(sandbox, agent_body, step_count):
    motors = agent_body.get("motors", []) if isinstance(agent_body, dict) else []
    if not motors:
        return
    if hasattr(sandbox, 'set_awake'):
        for body in sandbox.bodies:
            sandbox.set_awake(body, True)
    # Continuous sweeping motion with high speed to remove particles
    sandbox.set_motor(motors[0], motor_speed=15.0, max_torque=10.0)
